messages.content:
{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": []
  },
  "frozen_questions": [
    {
      "gap": "缺三月三日作为上巳节、文士集会赋诗的节候及习俗信息，以理解'会作诗'的场合与氛围。",
      "question_id": "Q1",
      "story_span": "三月三日㑹作詩"
    },
    {
      "gap": "缺桓公即桓温的身份信息，影响理解郝隆'千里投公'所投奔对象的权势地位，以及由此产生的政治意味。",
      "question_id": "Q2",
      "story_span": "桓公"
    },
    {
      "gap": "缺'参军'这一官位在晋代幕府中属较低级属官的信息，否则郝隆以'蛮府参军'自嘲的幽默感难以充分体现。",
      "question_id": "Q3",
      "story_span": "始得蠻府叅\n軍"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "collation_note",
        "ref": "J01",
        "source_labels": [],
        "speaker": null,
        "text": "「三月三日會，作詩。不能者」渚宮舊事五作「三月三日大會參佐，令賦詩，遲者」。「三升」景宋本及沈本作「三斗」。"
      },
      {
        "layer": "collation_note",
        "ref": "J02",
        "source_labels": [],
        "speaker": null,
        "text": "「蠻語也」渚宮舊事五無「也」字，「語」下有「溫大笑」三字。"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "郝隆為桓公南蠻叅軍三月三日㑹作詩不能者罰\n\n酒三升隆初以不能受罰既飲攬筆便作一句云娵\n隅躍清池桓問娵隅是何物荅曰蠻名魚為娵隅桓\n公曰作詩何以作蠻語隆曰千里投公始得蠻府叅\n軍那得不作蠻語也"
  },
  "story_id": "25-paidiao-035"
}
